using System;
using Ashfall.Core;
using Ashfall.Modules.WeaponHandling;
class AdversarialTests {
 sealed class Gate:IAuthorityGate { public bool Allow=true; public RuleResult Validate(CommandContext c){return Allow?RuleResult.Accept():RuleResult.Reject("denied");} }
 sealed class Ammo:IAmmoReserve { public int Count=100,Room=1000; public int Available {get{return Count;}} public int Take(int n){int a=Math.Min(n,Count);Count-=a;return a;} public int Refund(int n){int a=Math.Min(n,Room);Count+=a;Room-=a;return a;} }
 sealed class Rig {public Ammo A=new Ammo();public Gate G=new Gate(); public WeaponHandling W; public HandlingInput I;public long N;
 public Rig(bool p){W=TestSpawn.New("s","a",1,p?WeaponMechanism.PrecisionRifle:WeaponMechanism.ServiceRifle,A,G);I=new HandlingInput{Enabled=true,PrimaryTracked=true,SupportTracked=true,Desktop=true,ForegripDistance=1};}
 public RuleResult Do(HandlingAction a){N++;I.Sequence=N;return W.Apply(new CommandContext("s","a","c"+N,N,1,true),a,I);}
 public RuleResult At(float x,float y,float z,bool grip){I.SupportLocal=new Float3(x,y,z);I.Grip=grip;return Do(HandlingAction.Sample);}}
 static int pass,findings;
 static void Check(bool b,string s){if(!b)throw new Exception(s);pass++;Console.WriteLine("PASS "+s);}
 static void Finding(bool b,string s){if(!b)throw new Exception("Not reproduced: "+s);findings++;Console.WriteLine("REPRODUCED "+s);}
 static void Main(){
 var r=new Rig(false);r.A.Room=5;Check(!r.Do(HandlingAction.Eject).Accepted,"partial refund rejects");Check(r.W.Snapshot.Loaded+r.A.Count==124,"partial refund conserves total");r.A.Room=100;Check(r.Do(HandlingAction.Eject).Accepted&&r.A.Count==124,"refund retry returns only remaining rounds");
 var seated=new Rig(false);seated.Do(HandlingAction.Eject);seated.Do(HandlingAction.ReloadStep);seated.A.Room=2;Check(!seated.Do(HandlingAction.Eject).Accepted&&seated.W.Snapshot.Seated==22&&!seated.W.Snapshot.Chambered,"partial seated refund retains unchambered remainder");seated.Do(HandlingAction.ReloadStep);Check(seated.W.Snapshot.Loaded==22&&seated.A.Count==102,"rack after partial seated refund conserves ammo");
 var p=new Rig(true);p.A.Room=1;p.Do(HandlingAction.Eject);Check(!p.Do(HandlingAction.ReloadStep).Accepted&&p.W.Snapshot.Loaded==2&&p.A.Count==101,"precision failed refund preserves remaining magazine");p.A.Room=100;Check(p.Do(HandlingAction.ReloadStep).Accepted&&p.A.Count==103&&p.W.Snapshot.Phase==ReloadPhase.NeedsMagazine,"precision retry conserves total");
 for(int mode=0;mode<3;mode++){var t=new Rig(false);t.I.Desktop=false;t.Do(HandlingAction.Eject);t.At(0,-.278f,.15f,true);t.At(0,-.18f,.15f,true);t.At(-.045f,.064f,.10f,false);t.At(-.045f,.064f,.10f,true);t.At(-.045f,.064f,.05f,true);if(mode==0)t.I.PrimaryTracked=false;else if(mode==1)t.I.Paused=true;else t.I.HeadObstructed=true;t.Do(HandlingAction.Sample);t.I.PrimaryTracked=true;t.I.Paused=t.I.HeadObstructed=false;t.At(-.045f,.064f,-.1f,true);Check(!t.W.Snapshot.Chambered&&!t.W.Snapshot.ClaimsSupport,"held grip cannot resume after unavailable mode="+mode);t.At(-.045f,.064f,.1f,false);t.At(-.045f,.064f,.1f,true);t.At(-.045f,.064f,.02f,true);Check(t.W.Snapshot.Chambered,"fresh contact recovers mode="+mode);}
 var gate=new Rig(false);gate.G.Allow=false;gate.I.Trigger=true;Check(!gate.Do(HandlingAction.Fire).Accepted&&gate.W.Snapshot.Loaded==24,"external gate veto before mutation");gate.G.Allow=true;Check(gate.Do(HandlingAction.Fire).Accepted,"gate veto does not poison subsequent valid input");
 var invalid=new Rig(false);invalid.I.DeltaSeconds=float.PositiveInfinity;Check(!invalid.Do(HandlingAction.Eject).Accepted&&invalid.W.Snapshot.Loaded==24,"infinite delta no mutation");invalid.I.DeltaSeconds=0;invalid.I.SupportLocal=new Float3(float.NaN,0,0);Check(!invalid.Do(HandlingAction.Eject).Accepted,"NaN pose rejected");invalid.I.SupportLocal=new Float3();Check(!invalid.Do((HandlingAction)99).Accepted,"unknown action rejected");
 var win=new Rig(false);win.Do(HandlingAction.Sample);for(int n=0;n<256;n++)win.Do(HandlingAction.Sample);win.I.Sequence=1;Check(!win.W.Apply(new CommandContext("s","a","c1",1,1,true),HandlingAction.Eject,win.I).Accepted,"original replay rejected after ID eviction");win.I.Sequence=300;Check(win.W.Apply(new CommandContext("s","a","c1",300,1,true),HandlingAction.Eject,win.I).Accepted,"ID reuse with fresh envelope outside documented window accepted");
 var neg=new Rig(false);neg.I.Sequence=0;neg.I.Trigger=true;Check(!neg.W.Apply(new CommandContext("s","a","negative",-1,1,true),HandlingAction.Fire,neg.I).Accepted,"negative tick rejected locally");
 var max=new Rig(false);max.I.Sequence=long.MaxValue;Check(max.W.Apply(new CommandContext("s","a","max",long.MaxValue,1,true),HandlingAction.Sample,max.I).Accepted,"max tick and sequence accepted without arithmetic overflow");max.I.Sequence=0;Check(!max.W.Apply(new CommandContext("s","a","wrap",0,1,true),HandlingAction.Eject,max.I).Accepted,"wrapped sequence rejected; new lifetime needed");
 var timer=new Rig(false);timer.Do(HandlingAction.ReloadStep);timer.Do(HandlingAction.ReloadStep);timer.Do(HandlingAction.ReloadStep);timer.Do(HandlingAction.Sample);timer.I.Trigger=true;Check(!timer.Do(HandlingAction.Fire).Accepted,"rifle cannot fire at zero time after rack");
 var cadence=new Rig(false);cadence.I.Trigger=true;cadence.Do(HandlingAction.Fire);cadence.I.DeltaSeconds=.05f;for(int n=0;n<20;n++)cadence.Do(HandlingAction.Fire);Console.WriteLine("OBSERVED 50ms cadence shots="+cadence.W.Snapshot.Shots+" over 1s; source overrun-preserving cadence expects 9 including t0");Check(cadence.W.Snapshot.Shots==9,"service preserves bounded cadence overrun");
 var scope=new ScopeRules();scope.Sample(true,true,true,true,false,false,true,true,true,false,0,1);Check(scope.Active&&scope.Magnification==4,"held forward stick on scope entry does not zoom");scope.Sample(true,true,true,true,false,false,true,true,false,false,0,0);scope.Sample(true,true,true,true,false,false,true,true,false,false,0,1);Check(scope.Active&&scope.Magnification==8,"fresh stick zoom while latched without support");scope.Sample(true,true,true,false,false,false,true,true,false,false,0,0);Check(!scope.Active&&scope.Magnification==4,"scope tracking loss clears activation and zoom");scope.Sample(true,true,true,true,false,false,true,true,false,false,0,0);Check(!scope.Active,"scope cannot latch from unsupported held grip after loss");Check(ScopeRules.SupportAimWeight(new Float3(0,0,1),new Float3(0,0,-1),1,1)==0,"backward aim cone rejected");
 var equip=new Rig(false);equip.I.Trigger=true;equip.Do(HandlingAction.Fire);var recreated=new WeaponHandling("s","a",2,WeaponMechanism.ServiceRifle,equip.A,equip.G);Check(recreated.Snapshot.Loaded==0&&equip.W.Snapshot.Loaded==23&&equip.A.Count==100,"bare reconstruction grants no ammunition");
 Console.WriteLine("PASS assertions="+pass+" reproduced-findings="+findings);
 }
}
